solution:
def is_not_prime(n):
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True

    i = 3
    while i * i <= n:
        if n % i == 0:
            return True
        i += 2

    return False

import heapq

def heap_queue_largest(numbers, n):
    return heapq.nlargest(n, numbers)

def differ_At_One_Bit_Pos(x, y):
    n = x ^ y
    return n != 0 and (n & (n - 1)) == 0

def find_Rotations(s):
    if not s:
        return 0

    rotations = (s + s).find(s, 1)
    return rotations if rotations != -1 else len(s)

def remove_Occ(str1, ch):
    if not ch:
        return str1

    first = str1.find(ch)
    if first == -1:
        return str1

    last = str1.rfind(ch)

    if first == last:
        return str1[:first] + str1[first + len(ch):]

    str1 = str1[:last] + str1[last + len(ch):]
    str1 = str1[:first] + str1[first + len(ch):]
    return str1

def find_Volume(a, b, c):
    volume = a * b * c / 2
    return int(volume) if volume == int(volume) else volume

import re

def text_lowercase_underscore(text):
    return bool(re.fullmatch(r"[a-z]+_[a-z]+", text))

def remove_dirty_chars(str1, str2):
    dirty_chars = set(str2)
    return ''.join(char for char in str1 if char not in dirty_chars)

def test_duplicate(arr):
    seen = set()
    for num in arr:
        if num in seen:
            return True
        seen.add(num)
    return False

def is_woodall(n):
    if n <= 0:
        return False

    k = 1
    while True:
        value = k * (2 ** k) - 1
        if value == n:
            return True
        if value > n:
            return False
        k += 1

def check(n):
    if n < 0:
        return False
    reversed_n = int(str(n)[::-1])
    return n == 2 * reversed_n - 1

def find_Max_Num(digits):
    if not digits:
        return 0
    return int(''.join(map(str, sorted(digits, reverse=True))))

def count_Substrings(s):
    prefix_sum = 0
    count = 0
    freq = {0: 1}

    for ch in s:
        prefix_sum += int(ch) - 1
        count += freq.get(prefix_sum, 0)
        freq[prefix_sum] = freq.get(prefix_sum, 0) + 1

    return count

def recursive_list_sum(data):
    total = 0
    for item in data:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def bell_number(n):
    if n < 0:
        return 0

    bell = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    bell[0][0] = 1

    for i in range(1, n + 1):
        bell[i][0] = bell[i - 1][i - 1]
        for j in range(1, i + 1):
            bell[i][j] = bell[i][j - 1] + bell[i - 1][j - 1]

    return bell[n][0]

def is_Monotonic(arr):
    increasing = True
    decreasing = True

    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            increasing = False
        if arr[i] < arr[i + 1]:
            decreasing = False

    return increasing or decreasing

def is_sublist(lst, sublst):
    if not sublst:
        return True
    if len(sublst) > len(lst):
        return False

    sub_len = len(sublst)
    for i in range(len(lst) - sub_len + 1):
        if lst[i:i + sub_len] == sublst:
            return True
    return False

def get_equal(tuples_list):
    if not tuples_list:
        return True

    reference_length = len(tuples_list[0])
    for item in tuples_list:
        if len(item) != reference_length:
            return False

    return True

def comb_sort(list1):
    gap = len(list1)
    shrink = 1.3
    swapped = True

    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1

        swapped = False
        for i in range(len(list1) - gap):
            if list1[i] > list1[i + gap]:
                list1[i], list1[i + gap] = list1[i + gap], list1[i]
                swapped = True

    return list1

def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern and color_to_pattern[color] != pattern:
            return False
        if pattern in pattern_to_color and pattern_to_color[pattern] != color:
            return False

        color_to_pattern[color] = pattern
        pattern_to_color[pattern] = color

    return True

import math

def volume_sphere(radius):
    return (4.0 / 3.0) * math.pi * (radius ** 3)

def sequence(n):
    if n <= 0:
        return 0
    if n <= 2:
        return 1

    dp = [0] * (n + 1)
    dp[1] = dp[2] = 1

    for i in range(3, n + 1):
        prev = dp[i - 1]
        dp[i] = dp[prev] + dp[i - prev]

    return dp[n]

import math

def surfacearea_sphere(radius):
    return 4 * math.pi * radius ** 2

