def common_in_nested_lists(nested_list):
    if not nested_list:
        return []

    common_elements = set(nested_list[0])
    for inner_list in nested_list[1:]:
        common_elements &= set(inner_list)

    return list(common_elements)

def check_integer(s):
    if not isinstance(s, str):
        return False

    s = s.strip()
    if not s:
        return False

    if s[0] in "+-":
        s = s[1:]
        if not s:
            return False

    return s.isdigit()

def search(arr):
    if not arr:
        return None

    low, high = 0, len(arr) - 1

    while low < high:
        mid = (low + high) // 2

        if mid % 2 == 1:
            mid -= 1

        if arr[mid] == arr[mid + 1]:
            low = mid + 2
        else:
            high = mid

    return arr[low]

def amicable_numbers_sum(n):
    if n <= 1:
        return 0

    divisor_sums = [0] * (n + 1)
    for divisor in range(1, n // 2 + 1):
        for multiple in range(divisor * 2, n + 1, divisor):
            divisor_sums[multiple] += divisor

    cache = {}

    def sum_proper_divisors(num):
        if num <= 1:
            return 0
        if num <= n:
            return divisor_sums[num]
        if num in cache:
            return cache[num]

        total = 1
        d = 2
        while d * d <= num:
            if num % d == 0:
                total += d
                other = num // d
                if other != d:
                    total += other
            d += 1

        cache[num] = total
        return total

    total = 0
    for a in range(1, n + 1):
        b = divisor_sums[a]
        if b != a and b > 0 and sum_proper_divisors(b) == a:
            total += a

    return total

import cmath

def angle_complex(real, imag):
    return cmath.phase(real + imag)

def find_length(binary_string):
    if not binary_string:
        return 0

    current_sum = 1 if binary_string[0] == '0' else -1
    max_sum = current_sum

    for ch in binary_string[1:]:
        value = 1 if ch == '0' else -1
        current_sum = max(value, current_sum + value)
        max_sum = max(max_sum, current_sum)

    return max_sum

from math import gcd

def sum(num1, num2):
    g = gcd(num1, num2)
    if g == 0:
        return 0

    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            other = g // i
            if other != i:
                total += other
        i += 1

    return total

def magic_square_test(matrix):
    try:
        n = len(matrix)
    except TypeError:
        return False

    if n == 0:
        return False

    for row in matrix:
        try:
            if len(row) != n:
                return False
        except TypeError:
            return False

    try:
        target_sum = sum(matrix[0])

        for row in matrix:
            if sum(row) != target_sum:
                return False

        for col in range(n):
            if sum(matrix[row][col] for row in range(n)) != target_sum:
                return False

        if sum(matrix[i][i] for i in range(n)) != target_sum:
            return False

        if sum(matrix[i][n - 1 - i] for i in range(n)) != target_sum:
            return False

    except (TypeError, IndexError):
        return False

    return True
